export default `:root{--primary-color: #003366;--secondary-color: #0056b3;--background-color: #ffffff;--text-color: #333333;--light-gray: #f8f9fa;--border-color: #e9ecef;--success-color: #28a745;--warning-color: #ffc107;--danger-color: #dc3545;--font-family: "Roboto", "Inter", sans-serif;--font-size-base: 16px;--border-radius: 8px;--box-shadow: 0 2px 4px rgba(0, 0, 0, .1)}*{box-sizing:border-box}body{margin:0;font-family:var(--font-family);font-size:var(--font-size-base);line-height:1.6;color:var(--text-color);background-color:var(--background-color)}h1,h2,h3,h4,h5,h6{margin:0 0 1rem;font-weight:600;color:var(--primary-color)}p{margin:0 0 1rem}a{color:var(--secondary-color);text-decoration:none}a:hover{text-decoration:underline}.btn{display:inline-block;padding:.75rem 1.5rem;border:none;border-radius:var(--border-radius);font-size:1rem;font-weight:500;text-align:center;cursor:pointer;transition:all .3s ease}.btn-primary{background-color:var(--primary-color);color:#fff}.btn-primary:hover{background-color:var(--secondary-color);transform:translateY(-1px);box-shadow:var(--box-shadow)}.btn-secondary{background-color:var(--light-gray);color:var(--text-color);border:1px solid var(--border-color)}.btn-secondary:hover{background-color:var(--border-color)}.card{background-color:var(--background-color);border:1px solid var(--border-color);border-radius:var(--border-radius);box-shadow:var(--box-shadow);padding:1.5rem;margin-bottom:1rem}.card-header{border-bottom:1px solid var(--border-color);padding-bottom:1rem;margin-bottom:1rem;font-size:1.25rem;font-weight:600;color:var(--primary-color)}.card-body{padding:0}.form-group{margin-bottom:1rem}.form-label{display:block;margin-bottom:.5rem;font-weight:500;color:var(--text-color)}.form-control{width:100%;padding:.75rem;border:1px solid var(--border-color);border-radius:var(--border-radius);font-size:1rem;transition:border-color .3s ease}.form-control:focus{outline:none;border-color:var(--secondary-color);box-shadow:0 0 0 2px #0056b333}textarea.form-control{resize:vertical;min-height:100px}.grid{display:grid;gap:1rem}.grid-2{grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}.grid-3{grid-template-columns:repeat(auto-fit,minmax(250px,1fr))}.grid-4{grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}.text-center{text-align:center}.mb-0{margin-bottom:0}.mb-1{margin-bottom:.5rem}.mb-2{margin-bottom:1rem}.mb-3{margin-bottom:1.5rem}.mt-0{margin-top:0}.mt-1{margin-top:.5rem}.mt-2{margin-top:1rem}.mt-3{margin-top:1.5rem}.p-1{padding:.5rem}.p-2{padding:1rem}.p-3{padding:1.5rem}@media(max-width:768px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr}.btn{width:100%}}
`;